import type { CanMatchFn, Routes } from "@angular/router";

import frontendRegistryData from "./generated/frontend-registry.json";
import frontendCatalogData from "./generated/frontend-catalog.json";
import {
  isRunnableBrowserCell,
  readAngularRuntimeConfig,
} from "./cell-context";
import type { BrowserCellCatalog } from "./cell-context";

type FeatureSupport = Record<string, { angular?: { state?: string } }>;

const support = frontendRegistryData.feature_support as FeatureSupport;
const supportedFeatures = Object.entries(support)
  .filter(([, declaration]) => declaration.angular?.state === "supported")
  .map(([feature]) => feature)
  .sort();

const catalog = frontendCatalogData as BrowserCellCatalog;
export type FeatureComponentKey =
  | "popup"
  | "sidebar"
  | "chat-slots"
  | "chat-css"
  | "headless-simple"
  | "headless-complete"
  | "tools"
  | "interrupt"
  | "a2ui"
  | "generated-ui"
  | "mcp-apps"
  | "state"
  | "reasoning"
  | "agent-state"
  | "app-settings"
  | "media"
  | "beautiful-chat"
  | "mastra"
  | "chat";

/** Select the smallest lazy feature family that implements a showcase route. */
export function resolveFeatureComponentKey(
  feature: string,
): FeatureComponentKey {
  switch (feature) {
    case "prebuilt-popup":
      return "popup";
    case "prebuilt-sidebar":
      return "sidebar";
    case "chat-slots":
      return "chat-slots";
    case "chat-customization-css":
      return "chat-css";
    case "headless-simple":
      return "headless-simple";
    case "headless-complete":
      return "headless-complete";
    case "gen-ui-tool-based":
    case "tool-rendering-default-catchall":
    case "tool-rendering-custom-catchall":
    case "tool-rendering":
    case "tool-rendering-reasoning-chain":
    case "frontend-tools":
    case "frontend-tools-async":
    case "threadid-frontend-tool-roundtrip":
    case "hitl-in-chat":
    case "hitl-in-app":
      return "tools";
    case "gen-ui-interrupt":
    case "interrupt-headless":
      return "interrupt";
    case "declarative-gen-ui":
    case "a2ui-fixed-schema":
    case "a2ui-recovery":
      return "a2ui";
    case "open-gen-ui":
    case "open-gen-ui-advanced":
      return "generated-ui";
    case "mcp-apps":
      return "mcp-apps";
    case "shared-state-read-write":
    case "shared-state-read":
    case "shared-state-streaming":
    case "readonly-state-agent-context":
      return "state";
    case "reasoning-default":
    case "reasoning-custom":
      return "reasoning";
    case "gen-ui-agent":
    case "subagents":
      return "agent-state";
    case "background-agents":
    case "observational-memory":
    case "browser-use":
      return "mastra";
    case "auth":
    case "agent-config":
      return "app-settings";
    case "voice":
    case "multimodal":
      return "media";
    case "beautiful-chat":
      return "beautiful-chat";
    case "agentic-chat":
      return "chat";
    default:
      throw new Error(
        `Feature "${feature}" does not have an Angular implementation.`,
      );
  }
}

/** Resolve a feature to its canonical lazy Angular implementation. */
function loadFeatureComponent(feature: string) {
  switch (resolveFeatureComponentKey(feature)) {
    case "popup":
      return () =>
        import("./features/popup-feature.component").then(
          (module) => module.PopupFeatureComponent,
        );
    case "mastra":
      return () =>
        import("./features/mastra/mastra-feature.component").then(
          (module) => module.MastraFeatureComponent,
        );
    case "sidebar":
      return () =>
        import("./features/sidebar-feature.component").then(
          (module) => module.SidebarFeatureComponent,
        );
    case "chat-slots":
      return () =>
        import("./features/chat-slots-feature.component").then(
          (module) => module.ChatSlotsFeatureComponent,
        );
    case "chat-css":
      return () =>
        import("./features/chat-css-feature.component").then(
          (module) => module.ChatCssFeatureComponent,
        );
    case "headless-simple":
      return () =>
        import("./features/headless/headless-simple-feature.component").then(
          (module) => module.HeadlessSimpleFeatureComponent,
        );
    case "headless-complete":
      return () =>
        import("./features/headless/headless-complete-feature.component").then(
          (module) => module.HeadlessCompleteFeatureComponent,
        );
    case "tools":
      return () =>
        import("./features/tools/tool-feature.component").then(
          (module) => module.ToolFeatureComponent,
        );
    case "interrupt":
      return () =>
        import("./features/interrupt/interrupt-feature.component").then(
          (module) => module.InterruptFeatureComponent,
        );
    case "a2ui":
      return () =>
        import("./features/a2ui/a2ui-feature.component").then(
          (module) => module.A2UIFeatureComponent,
        );
    case "generated-ui":
      return () =>
        import("./features/generated-ui/generated-ui-feature.component").then(
          (module) => module.GeneratedUIFeatureComponent,
        );
    case "mcp-apps":
      return () =>
        import("./features/generated-ui/mcp-apps-feature.component").then(
          (module) => module.MCPAppsFeatureComponent,
        );
    case "state":
      return () =>
        import("./features/state/state-feature.component").then(
          (module) => module.StateFeatureComponent,
        );
    case "reasoning":
      return () =>
        import("./features/reasoning-feature.component").then(
          (module) => module.ReasoningFeatureComponent,
        );
    case "agent-state":
      return () =>
        import("./features/agent-state/agent-state-feature.component").then(
          (module) => module.AgentStateFeatureComponent,
        );
    case "app-settings":
      return () =>
        import("./features/app-settings/app-settings-feature.component").then(
          (module) => module.AppSettingsFeatureComponent,
        );
    case "media":
      return () =>
        import("./features/media/media-feature.component").then(
          (module) => module.MediaFeatureComponent,
        );
    case "beautiful-chat":
      return () =>
        import("./features/beautiful-chat/beautiful-chat-feature.component").then(
          (module) => module.BeautifulChatFeatureComponent,
        );
    case "chat":
      return () =>
        import("./features/chat-feature.component").then(
          (module) => module.ChatFeatureComponent,
        );
  }
}

const canMatchRunnableCell: CanMatchFn = (route) => {
  const integration = readAngularRuntimeConfig()?.integrationId ?? "";
  const feature = route.data?.["feature"];
  return (
    typeof feature === "string" &&
    isRunnableBrowserCell(integration, feature, catalog)
  );
};

export const routes: Routes = [
  ...supportedFeatures.map((feature) => ({
    path: feature,
    title: `CopilotKit Angular — ${feature}`,
    data: { feature },
    canMatch: [canMatchRunnableCell],
    loadComponent: loadFeatureComponent(feature),
  })),
  {
    path: "**",
    title: "Angular Showcase — Unavailable",
    loadComponent: () =>
      import("./features/unavailable-feature.component").then(
        (module) => module.UnavailableFeatureComponent,
      ),
  },
];

cell-context.ts.content:
export interface BrowserCellCatalog {
  cells: Array<{
    id: string;
    frontend: string;
    integration: string;
    feature: string;
    frontend_status: string;
    backend_status: string;
    runnable: boolean;
    exception: { reason: string } | null;
  }>;
}

export interface AngularRuntimeConfig {
  frontendId: "angular";
  integrationId: string;
}

export type BrowserCellResolution =
  | {
      kind: "runnable";
      cellId: string;
      integration: string;
      feature: string;
      runtimeUrl: string;
    }
  | {
      kind: "unavailable";
      cellId: string;
      integration: string;
      feature: string;
      reason: string;
    }
  | { kind: "malformed"; reason: string };

const FEATURE_PATH_RE = /^\/angular\/([a-z0-9][a-z0-9-]*[a-z0-9])\/?$/;
const SAFE_ID_RE = /^[a-z0-9][a-z0-9-]*[a-z0-9]$/;

/** Read the bounded, non-secret manifest staged by the integration image. */
export function readAngularRuntimeConfig(): AngularRuntimeConfig | undefined {
  const candidate = (
    globalThis as typeof globalThis & {
      __COPILOTKIT_SHOWCASE__?: unknown;
    }
  ).__COPILOTKIT_SHOWCASE__;
  if (typeof candidate !== "object" || candidate === null) return undefined;
  const manifest = candidate as Record<string, unknown>;
  const keys = Object.keys(manifest).sort();
  if (
    keys.length !== 2 ||
    keys[0] !== "frontendId" ||
    keys[1] !== "integrationId" ||
    manifest["frontendId"] !== "angular" ||
    typeof manifest["integrationId"] !== "string" ||
    !SAFE_ID_RE.test(manifest["integrationId"])
  ) {
    return undefined;
  }
  return {
    frontendId: "angular",
    integrationId: manifest["integrationId"],
  };
}

const RUNTIME_PATHS: Readonly<Record<string, string>> = {
  "a2ui-fixed-schema": "/api/copilotkit-a2ui-fixed-schema",
  "a2ui-recovery": "/api/copilotkit-a2ui-recovery",
  "agent-config": "/api/copilotkit-agent-config",
  auth: "/api/copilotkit-auth",
  "background-agents": "/api/copilotkit-background-agents",
  "beautiful-chat": "/api/copilotkit-beautiful-chat",
  "browser-use": "/api/copilotkit-browser-use",
  "declarative-gen-ui": "/api/copilotkit-declarative-gen-ui",
  "headless-complete": "/api/copilotkit-mcp-apps",
  "mcp-apps": "/api/copilotkit-mcp-apps",
  multimodal: "/api/copilotkit-multimodal",
  "observational-memory": "/api/copilotkit-observational-memory",
  "open-gen-ui": "/api/copilotkit-ogui",
  "open-gen-ui-advanced": "/api/copilotkit-ogui",
  voice: "/api/copilotkit-voice",
};

/** Resolve the existing same-origin runtime route for one feature. */
export function runtimePathForFeature(feature: string): string {
  return RUNTIME_PATHS[feature] ?? "/api/copilotkit";
}

/** Resolve a browser pathname without decoding or accepting extra segments. */
export function resolveBrowserCell(
  pathname: string,
  catalog: BrowserCellCatalog,
  runtimeConfig = readAngularRuntimeConfig(),
): BrowserCellResolution {
  const match = FEATURE_PATH_RE.exec(pathname);
  if (!match) {
    return { kind: "malformed", reason: "The demo route is malformed." };
  }
  if (runtimeConfig === undefined) {
    return {
      kind: "malformed",
      reason: "The integration runtime manifest is missing or invalid.",
    };
  }
  const integration = runtimeConfig.integrationId;
  const feature = match[1];
  const cellId = `angular/${integration}/${feature}`;
  const cell = catalog.cells.find((candidate) => candidate.id === cellId);
  if (!cell) {
    return { kind: "malformed", reason: "The demo cell is not declared." };
  }
  if (!cell.runnable) {
    return {
      kind: "unavailable",
      cellId,
      integration,
      feature,
      reason:
        cell.exception?.reason ??
        `This ${cell.frontend_status} frontend and ${cell.backend_status} backend intersection is not runnable.`,
    };
  }
  return {
    kind: "runnable",
    cellId,
    integration,
    feature,
    runtimeUrl: runtimePathForFeature(feature),
  };
}

/** Report whether one exact frontend/backend/feature cell may load demo code. */
export function isRunnableBrowserCell(
  integration: string,
  feature: string,
  catalog: BrowserCellCatalog,
): boolean {
  return (
    resolveBrowserCell(`/angular/${feature}`, catalog, {
      frontendId: "angular",
      integrationId: integration,
    }).kind === "runnable"
  );
}

/** Keep unknown tool disclosure opt-in and scoped to its dedicated demo. */
export function isDefaultToolRenderingCell(feature: string): boolean {
  return feature === "tool-rendering-default-catchall";
}

feature-agent.ts.content:
import { integrationId } from "./runtime-context";

const AGENT_BY_FEATURE: Readonly<Record<string, string>> = {
  "agent-config": "agent-config-demo",
  "agentic-chat": "agentic_chat",
  auth: "auth-demo",
  "frontend-tools": "frontend_tools",
  multimodal: "multimodal-demo",
  voice: "voice-demo",
};

const INTEGRATION_AGENT_OVERRIDES: Readonly<Record<string, string>> = {
  "llamaindex/reasoning-custom": "agentic-chat-reasoning",
  "llamaindex/reasoning-default": "reasoning-default-render",
  "pydantic-ai/frontend-tools": "frontend-tools",
};

const THREAD_ID_OVERRIDES: Readonly<Record<string, string>> = {
  "threadid-frontend-tool-roundtrip": "a9e7e9c4-6c72-4b8a-9d74-c5c0e05f6580",
};

/** Resolve the backend agent used by an exact shared integration contract. */
export function agentIdForFeature(
  feature: string,
  integration: string,
): string {
  const integrationOverride =
    INTEGRATION_AGENT_OVERRIDES[`${integration}/${feature}`];
  if (integrationOverride) {
    return integrationOverride;
  }
  return AGENT_BY_FEATURE[feature] ?? feature;
}

/** Resolve the backend agent for the integration hosting this Angular app. */
export function agentIdForCurrentIntegration(feature: string): string {
  return agentIdForFeature(feature, integrationId());
}

/** Resolve an explicit thread required by a feature-level regression contract. */
export function threadIdForFeature(feature: string): string | undefined {
  return THREAD_ID_OVERRIDES[feature];
}

