import type {
  AttachmentsConfig,
  RenderToolCallConfig,
} from "@copilotkit/angular";
import {
  ChangeDetectionStrategy,
  Component,
  effect,
  inject,
  signal,
  viewChild,
} from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import {
  CopilotKit,
  injectAgentStore,
  registerRenderToolCall,
} from "@copilotkit/angular";
import { z } from "zod";

import { agentIdForCurrentIntegration } from "../../feature-agent";
import { FeatureHeaderComponent } from "../feature-header.component";
import { ShowcaseChatHostComponent } from "../showcase-chat-host.component";
import { WeatherToolCard } from "../tools/tool-cards";
import {
  createMultimodalMessage,
  dedupeUserMessageMedia,
  rewriteMessagesForLegacyConverter,
  validateSampleBytes,
  VOICE_WEATHER_TOOL_NAMES,
} from "./media-model";
import type { MediaAgentMessage, SampleSpec } from "./media-model";

const VOICE_SAMPLE_TEXT = "What is the weather in Tokyo?";

type VoiceWeatherArgs = Record<string, unknown>;

/** Exact backend weather tools rendered by the voice demo. */
export const voiceWeatherRendererConfigs: readonly RenderToolCallConfig<VoiceWeatherArgs>[] =
  VOICE_WEATHER_TOOL_NAMES.map((name) => ({
    name,
    args: z.record(z.unknown()),
    component:
      WeatherToolCard as unknown as RenderToolCallConfig<VoiceWeatherArgs>["component"],
  }));

const SAMPLES: readonly SampleSpec[] = [
  {
    buttonLabel: "Try with sample image",
    filename: "sample.png",
    mimeType: "image/png",
    testId: "multimodal-sample-image-button",
    fetchUrl: "/demo-files/sample.png",
    autoPrompt: "can you tell me what is in this demo image I just attached",
  },
  {
    buttonLabel: "Try with sample PDF",
    filename: "sample.pdf",
    mimeType: "application/pdf",
    testId: "multimodal-sample-pdf-button",
    fetchUrl: "/demo-files/sample.pdf",
    autoPrompt: "can you tell me what is in this demo pdf I just attached",
  },
];

const MULTIMODAL_ATTACHMENTS: AttachmentsConfig = {
  enabled: true,
  accept: "image/*,application/pdf",
  maxSize: 10 * 1024 * 1024,
};

@Component({
  selector: "showcase-media-feature",
  imports: [FeatureHeaderComponent, ShowcaseChatHostComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "feature-page" },
  template: `
    <showcase-feature-header />
    <main class="media-page">
      <section class="sample-panel" aria-label="Bundled media samples">
        @if (feature === "voice") {
          <div class="sample-copy">
            <strong>Voice input</strong>
            <span>Use the microphone, or insert a deterministic sample.</span>
          </div>
          <button
            type="button"
            data-testid="voice-sample-audio-button"
            [title]="'Inserts: &quot;' + voiceSampleText + '&quot;'"
            (click)="insertVoiceSample()"
          >
            <span aria-hidden="true">🎙</span>
            <span>Try a sample audio</span>
          </button>
        } @else {
          <div class="sample-copy">
            <strong>Bundled samples</strong>
            <span>Send a real image or PDF through the agent runtime.</span>
          </div>
          <div class="sample-actions">
            @for (sample of samples; track sample.testId) {
              <button
                type="button"
                [attr.data-testid]="sample.testId"
                [disabled]="loading() !== null"
                (click)="sendSample(sample)"
              >
                {{ loading() === sample.testId ? "Sending…" : sample.buttonLabel }}
              </button>
            }
          </div>
        }
        @if (error()) {
          <p class="sample-error" role="alert">{{ error() }}</p>
        }
      </section>
      <section class="chat-surface" aria-label="CopilotKit assistant">
        <showcase-chat-host
          [agentId]="agentId"
          [attachments]="
            feature === 'multimodal' ? multimodalAttachments : undefined
          "
        />
      </section>
    </main>
  `,
  styles: `
    .media-page {
      display: grid;
      min-height: 0;
      grid-template-rows: auto minmax(0, 1fr);
      gap: 0.75rem;
      padding: 0.75rem;
      background: #eef3f7;
    }
    .sample-panel {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      gap: 0.75rem 1rem;
      padding: 0.75rem 1rem;
      border: 1px solid #d8e0ea;
      border-radius: 0.9rem;
      background: #fff;
    }
    .sample-copy {
      display: grid;
      flex: 1 1 16rem;
      gap: 0.15rem;
      color: #14213d;
    }
    .sample-copy span {
      color: #52637a;
      font-size: 0.82rem;
    }
    .sample-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
    }
    button {
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding: 0.55rem 0.8rem;
      border: 1px solid #c7d2e0;
      border-radius: 0.65rem;
      color: #20324d;
      background: #fff;
      font: inherit;
      font-size: 0.84rem;
      font-weight: 650;
      cursor: pointer;
    }
    button:hover:not(:disabled) {
      border-color: #4263eb;
      background: #f5f7ff;
    }
    button:focus-visible {
      outline: 3px solid #91a7ff;
      outline-offset: 2px;
    }
    button:disabled {
      cursor: wait;
      opacity: 0.62;
    }
    .sample-error {
      flex-basis: 100%;
      margin: 0;
      color: #991b1b;
      font-size: 0.84rem;
    }
