import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
} from "@angular/core";

import type { Preferences, PreferenceTone } from "./state-model";
import { toggleValue } from "./state-model";

const INTERESTS = [
  "Cooking",
  "Travel",
  "Tech",
  "Music",
  "Sports",
  "Books",
  "Movies",
] as const;

@Component({
  selector: "showcase-preferences-panel",
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "state-card" },
  template: `
    <section data-testid="preferences-card" aria-labelledby="preferences-title">
      <h2 id="preferences-title">Your preferences</h2>
      <p>Written into agent state and read by the agent on every turn.</p>

      <label for="pref-name">Name</label>
      <input
        id="pref-name"
        data-testid="pref-name"
        type="text"
        [value]="value().name"
        placeholder="e.g. Atai"
        (input)="setName($event)"
      />

      <div class="field-grid">
        <div>
          <label for="pref-tone">Tone</label>
          <select
            id="pref-tone"
            data-testid="pref-tone"
            [value]="value().tone"
            (change)="setTone($event)"
          >
            <option value="formal">Formal</option>
            <option value="casual">Casual</option>
            <option value="playful">Playful</option>
          </select>
        </div>
        <div>
          <label for="pref-language">Language</label>
          <select
            id="pref-language"
            data-testid="pref-language"
            [value]="value().language"
            (change)="setLanguage($event)"
          >
            @for (language of languages; track language) {
              <option [value]="language">{{ language }}</option>
            }
          </select>
        </div>
      </div>

      <fieldset>
        <legend>Interests</legend>
        <div class="choice-list">
          @for (interest of interests; track interest) {
            <button
              type="button"
              [class.selected]="value().interests.includes(interest)"
              [attr.aria-pressed]="value().interests.includes(interest)"
              (click)="toggleInterest(interest)"
            >
              {{ interest }}
            </button>
          }
        </div>
      </fieldset>

      <span class="state-label">Shared state</span>
      <pre data-testid="pref-state-json">{{ stateJson() }}</pre>
    </section>
  `,
  styles: `
    :host {
      display: block;
    }
    section {
      display: grid;
      gap: 0.8rem;
      height: 100%;
      padding: 1.25rem;
      border: 1px solid #dbe3eb;
      background: #fff;
    }
    h2,
    p {
      margin: 0;
    }
    p {
      color: #52637a;
      font-size: 0.9rem;
    }
    label,
    legend {
      color: #31465e;
      font-size: 0.78rem;
      font-weight: 700;
    }
    input,
    select {
      width: 100%;
      min-height: 2.6rem;
      padding: 0.55rem 0.7rem;
      border: 1px solid #9fb3c8;
      border-radius: 0.35rem;
      background: #fff;
      font: inherit;
    }
    .field-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.8rem;
    }
    .field-grid > div {
      display: grid;
      gap: 0.35rem;
    }
    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }
    .choice-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.45rem;
      margin-top: 0.45rem;
    }
    button {
      padding: 0.4rem 0.65rem;
      border: 1px solid #9fb3c8;
      border-radius: 999px;
      color: #31465e;
      background: #fff;
      cursor: pointer;
    }
    button.selected {
      color: #fff;
      border-color: #1d4ed8;
      background: #1d4ed8;
    }
    :is(input, select, button):focus-visible {
      outline: 3px solid #2563eb;
      outline-offset: 2px;
    }
    .state-label {
      color: #64748b;
      font-size: 0.67rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }
    pre {
      min-height: 8rem;
      margin: 0;
      padding: 0.75rem;
      overflow: auto;
      border: 1px solid #e2e8f0;
      background: #f8fafc;
      font-size: 0.72rem;
    }
    @media (max-width: 38rem) {
      .field-grid {
        grid-template-columns: 1fr;
      }
    }
  `,
})
export class PreferencesPanelComponent {
  readonly value = input.required<Preferences>();
  readonly valueChange = output<Preferences>();
  protected readonly interests = INTERESTS;
  protected readonly languages = [
    "English",
    "Spanish",
    "French",
    "German",
    "Japanese",
  ];

  protected stateJson(): string {
    return JSON.stringify(this.value(), null, 2);
  }

  protected setName(event: Event): void {
    this.patch({ name: (event.target as HTMLInputElement).value });
  }

  protected setTone(event: Event): void {
    this.patch({
      tone: (event.target as HTMLSelectElement).value as PreferenceTone,
    });
  }

  protected setLanguage(event: Event): void {
    this.patch({ language: (event.target as HTMLSelectElement).value });
  }

  protected toggleInterest(interest: string): void {
    this.patch({ interests: toggleValue(this.value().interests, interest) });
  }

  private patch(change: Partial<Preferences>): void {
    this.valueChange.emit({ ...this.value(), ...change });
  }
}

features/state/recipe-panel.component.ts.content:
import {
  ChangeDetectionStrategy,
  Component,
  input,
  output,
} from "@angular/core";

import type { Ingredient, Recipe } from "./state-model";
import { toggleValue } from "./state-model";

const PREFERENCES = [
  "High Protein",
  "Low Carb",
  "Spicy",
  "Budget-Friendly",
  "One-Pot Meal",
  "Vegetarian",
  "Vegan",
] as const;

@Component({
  selector: "showcase-recipe-panel",
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <form data-testid="recipe-card" (submit)="$event.preventDefault()">
      <header>
        <p class="eyebrow">AI Recipe Assistant</p>
        <input
          aria-label="Recipe title"
          [value]="recipe().title"
          (input)="setTitle($event)"
        />
        <div class="field-grid">
          <label
            >Cooking time
            <select
              aria-label="Cooking time"
              [value]="recipe().cooking_time"
              (change)="setCookingTime($event)"
            >
              @for (time of cookingTimes; track time) {
                <option [value]="time">{{ time }}</option>
              }
            </select>
          </label>
          <label
            >Skill level
            <select
              aria-label="Skill level"
              [value]="recipe().skill_level"
              (change)="setSkillLevel($event)"
            >
              @for (level of skillLevels; track level) {
                <option [value]="level">{{ level }}</option>
              }
            </select>
          </label>
        </div>
      </header>

      <fieldset>
        <legend>Dietary Preferences</legend>
        <div class="choice-list">
          @for (preference of preferences; track preference) {
            <button
              type="button"
              [class.selected]="recipe().special_preferences.includes(preference)"
              [attr.aria-pressed]="
                recipe().special_preferences.includes(preference)
              "
              (click)="togglePreference(preference)"
            >
              {{ preference }}
            </button>
          }
        </div>
      </fieldset>

      <section aria-labelledby="ingredients-heading">
        <div class="section-heading">
          <h2 id="ingredients-heading">Ingredients</h2>
          <button
            data-testid="add-ingredient-button"
            type="button"
            (click)="addIngredient()"
          >
            + Add Ingredient
          </button>
        </div>
        <div data-testid="ingredients-container" class="rows">
          @for (ingredient of recipe().ingredients; track $index) {
            <div data-testid="ingredient-card" class="ingredient-row">
              <span aria-hidden="true">{{ ingredient.icon || "🍴" }}</span>
              <input
                [attr.aria-label]="'Ingredient ' + ($index + 1) + ' name'"
                placeholder="Ingredient name"
                [value]="ingredient.name"
                (input)="setIngredient($index, 'name', $event)"
              />
              <input
                [attr.aria-label]="'Ingredient ' + ($index + 1) + ' amount'"
                placeholder="Amount"
                [value]="ingredient.amount"
                (input)="setIngredient($index, 'amount', $event)"
              />
              <button
                type="button"
                [attr.aria-label]="'Remove ingredient ' + ($index + 1)"
                (click)="removeIngredient($index)"
              >
                ×
              </button>
            </div>
          }
        </div>
      </section>

      <section aria-labelledby="instructions-heading">
        <div class="section-heading">
          <h2 id="instructions-heading">Instructions</h2>
          <button type="button" (click)="addInstruction()">+ Add Step</button>
        </div>
        <div data-testid="instructions-container" class="rows">
          @for (instruction of recipe().instructions; track $index) {
            <div class="instruction-row">
              <span aria-hidden="true">{{ $index + 1 }}</span>
              <textarea
                [attr.aria-label]="'Instruction ' + ($index + 1)"
                [value]="instruction"
                (input)="setInstruction($index, $event)"
              ></textarea>
              <button
                type="button"
                [attr.aria-label]="'Remove step ' + ($index + 1)"
                (click)="removeInstruction($index)"
              >
                ×
              </button>
            </div>
          }
        </div>
      </section>

      <button
        data-testid="improve-button"
        class="improve"
        type="button"
        [disabled]="isRunning()"
        (click)="improve.emit()"
      >
        {{ isRunning() ? "Please Wait..." : "✦ Improve with AI" }}
      </button>
    </form>
  `,
  styles: `
    form {
      display: grid;
      gap: 1.25rem;
      padding: 1.25rem;
      border: 1px solid #dbe3eb;
      background: #fff;
    }
    header {
      display: grid;
      gap: 0.75rem;
    }
    .eyebrow {
      margin: 0;
      color: #52637a;
      font-size: 0.72rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }
    header > input {
      border: 0;
      border-bottom: 1px solid #dbe3eb;
      color: #14213d;
      font-size: clamp(1.5rem, 3vw, 2.2rem);
      font-weight: 700;
    }
    .field-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 0.75rem;
    }
    label {
      display: grid;
      gap: 0.35rem;
      color: #31465e;
      font-size: 0.78rem;
      font-weight: 700;
    }
    input,
    select,
    textarea {
      min-height: 2.5rem;
      padding: 0.55rem 0.7rem;
      border: 1px solid #9fb3c8;
      border-radius: 0.35rem;
      background: #fff;
      font: inherit;
    }
    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
    }
    legend,
    h2 {
      color: #14213d;
      font-size: 0.95rem;
      font-weight: 700;
    }
    h2 {
      margin: 0;
    }
    .choice-list {
      display: flex;
      flex-wrap: wrap;
      gap: 0.4rem;
      margin-top: 0.5rem;
    }
    button {
      padding: 0.42rem 0.7rem;
      border: 1px solid #9fb3c8;
      border-radius: 0.35rem;
      color: #31465e;
      background: #fff;
      cursor: pointer;
    }
    .choice-list button {
      border-radius: 999px;
    }
    button.selected,
    .improve {
      color: #fff;
      border-color: #1d4ed8;
      background: #1d4ed8;
    }
    :is(input, select, textarea, button):focus-visible {
      outline: 3px solid #2563eb;
      outline-offset: 2px;
    }
    .section-heading {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
    }
    .rows {
      display: grid;
      gap: 0.55rem;
      margin-top: 0.6rem;
    }
    .ingredient-row {
      display: grid;
      grid-template-columns: auto minmax(0, 1fr) minmax(7rem, 0.45fr) auto;
      align-items: center;
      gap: 0.55rem;
    }
    .ingredient-row > span {
      font-size: 1.5rem;
    }
    .instruction-row {
      display: grid;
      grid-template-columns: 2rem minmax(0, 1fr) auto;
      align-items: start;
      gap: 0.55rem;
    }
    .instruction-row > span {
      display: grid;
      width: 1.8rem;
      height: 1.8rem;
      place-items: center;
      border-radius: 50%;
      color: #fff;
      background: #1d4ed8;
    }
    textarea {
      min-height: 4rem;
      resize: vertical;
    }
    .improve {
      justify-self: center;
      padding: 0.65rem 1rem;
    }
    .improve:disabled {
      cursor: wait;
      opacity: 0.65;
    }
    @media (max-width: 44rem) {
      .field-grid {
        grid-template-columns: 1fr;
      }
      .ingredient-row {
        grid-template-columns: auto minmax(0, 1fr) auto;
      }
      .ingredient-row input:nth-of-type(2) {
        grid-column: 2;
      }
    }
  `,
})
export class RecipePanelComponent {
  readonly recipe = input.required<Recipe>();
  readonly isRunning = input(false);
  readonly recipeChange = output<Recipe>();
  readonly improve = output<void>();
  protected readonly cookingTimes: Recipe["cooking_time"][] = [
    "5 min",
    "15 min",
    "30 min",
    "45 min",
    "60+ min",
  ];
  protected readonly skillLevels: Recipe["skill_level"][] = [
    "Beginner",
    "Intermediate",
    "Advanced",
  ];
  protected readonly preferences = PREFERENCES;

  protected setTitle(event: Event): void {
    this.patch({ title: valueOf(event) });
  }

  protected setCookingTime(event: Event): void {
    this.patch({ cooking_time: valueOf(event) as Recipe["cooking_time"] });
  }

  protected setSkillLevel(event: Event): void {
    this.patch({ skill_level: valueOf(event) as Recipe["skill_level"] });
  }

  protected togglePreference(preference: string): void {
    this.patch({
      special_preferences: toggleValue(
        this.recipe().special_preferences,
        preference,
      ),
    });
  }

  protected addIngredient(): void {
    this.patch({
      ingredients: [
        ...this.recipe().ingredients,
        { icon: "🍴", name: "", amount: "" },
      ],
    });
  }

  protected setIngredient(
    index: number,
    field: keyof Ingredient,
    event: Event,
  ): void {
    const ingredients = this.recipe().ingredients.map((ingredient, candidate) =>
      candidate === index
        ? { ...ingredient, [field]: valueOf(event) }
        : ingredient,
    );
    this.patch({ ingredients });
  }

  protected removeIngredient(index: number): void {
    this.patch({
      ingredients: this.recipe().ingredients.filter(
        (_, candidate) => candidate !== index,
      ),
    });
  }

  protected addInstruction(): void {
    this.patch({ instructions: [...this.recipe().instructions, ""] });
  }

  protected setInstruction(index: number, event: Event): void {
    const instructions = this.recipe().instructions.map(
      (instruction, candidate) =>
        candidate === index ? valueOf(event) : instruction,
    );
    this.patch({ instructions });
  }

  protected removeInstruction(index: number): void {
    this.patch({
      instructions: this.recipe().instructions.filter(
        (_, candidate) => candidate !== index,
      ),
    });
  }

  private patch(change: Partial<Recipe>): void {
    this.recipeChange.emit({ ...this.recipe(), ...change });
  }
}

function valueOf(event: Event): string {
  return (
    event.target as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement
  ).value;
}

features/state/state-feature.component.t.content:
import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  signal,
} from "@angular/core";
import { ActivatedRoute } from "@angular/router";
import {
  CopilotKit,
  connectAgentContext,
  injectAgentStore,
} from "@copilotkit/angular";

import { agentIdForCurrentIntegration } from "../../feature-agent";
import { FeatureHeaderComponent } from "../feature-header.component";
import { ShowcaseChatHostComponent } from "../showcase-chat-host.component";
import { ACTIVITIES, ContextPanelComponent } from "./context-panel.component";
import { DocumentPanelComponent } from "./document-panel.component";
import { NotesPanelComponent } from "./notes-panel.component";
import { PreferencesPanelComponent } from "./preferences-panel.component";
import { RecipePanelComponent } from "./recipe-panel.component";
import {
  INITIAL_PREFERENCES,
  INITIAL_RECIPE,
  readDocumentState,
  readRecipeState,
  readWriteState,
} from "./state-model";
import type { Preferences, Recipe } from "./state-model";

@Component({
  selector: "showcase-state-feature",
  imports: [
    ContextPanelComponent,
    DocumentPanelComponent,
    FeatureHeaderComponent,
    NotesPanelComponent,
    PreferencesPanelComponent,
    RecipePanelComponent,
    ShowcaseChatHostComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: "feature-page" },
  template: `
    <showcase-feature-header />
    <main
      class="state-page"
      [class.context-page]="feature === 'readonly-state-agent-context'"
    >
      <section class="state-workspace" [attr.aria-label]="workspaceLabel()">
        @switch (feature) {
          @case ("shared-state-read-write") {
            <header class="intro">
              <h1>Shared state — read &amp; write</h1>
              <p>
                The UI writes preferences into agent state and reads the
                agent-authored scratch pad back.
              </p>
            </header>
            <div class="two-card-grid">
              <showcase-preferences-panel
                [value]="readWriteState().preferences"
                (valueChange)="setPreferences($event)"
              />
              <showcase-notes-panel
                [notes]="readWriteState().notes"
                (clear)="clearNotes()"
              />
            </div>
          }
          @case ("shared-state-read") {
            <showcase-recipe-panel
              [recipe]="recipe()"
              [isRunning]="isRunning()"
              (recipeChange)="setRecipe($event)"
              (improve)="improveRecipe()"
            />
          }
          @case ("shared-state-streaming") {
            <showcase-document-panel
              [content]="document()"
              [isStreaming]="isRunning()"
            />
          }
          @case ("readonly-state-agent-context") {
            <showcase-context-panel
              [userName]="userName()"
              [timezone]="timezone()"
              [recentActivity]="recentActivity()"
              (nameChange)="userName.set($event)"
              (timezoneChange)="timezone.set($event)"
              (activityChange)="recentActivity.set($event)"
            />
          }
        }
        @if (error()) {
          <p class="state-error" role="alert">{{ error() }}</p>
        }
      </section>
      <aside class="state-chat" aria-label="CopilotKit assistant">
        <showcase-chat-host [chatPlaceholder]="chatPlaceholder()" />
      </aside>
    </main>
  `,
  styles: `
    .state-page {
      display: grid;
      min-height: 0;
      grid-template-columns: minmax(0, 1fr) minmax(20rem, 26rem);
      background: #eef3f7;
    }
    .state-workspace {
      min-width: 0;
      padding: clamp(1rem, 3vw, 2.5rem);
      overflow: auto;
    }
    .state-chat {
      min-width: 0;
      border-left: 1px solid #dbe3eb;
      background: #fff;
    }
    .intro {
      margin-bottom: 1.25rem;
    }
    .intro h1 {
      margin: 0;
      color: #14213d;
      font-size: clamp(1.6rem, 3vw, 2.25rem);
    }
    .intro p {
      max-width: 42rem;
      margin: 0.5rem 0 0;
      color: #52637a;
    }
    .two-card-grid {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1rem;
      align-items: stretch;
    }
    .state-error {
      padding: 0.75rem;
      border: 1px solid #dc9b9b;
      color: #7f1d1d;
      background: #fff5f5;
    }
    @media (max-width: 64rem) {
      .state-page {
        grid-template-columns: 1fr;
        grid-template-rows: auto minmax(28rem, 48vh);
        overflow: auto;
      }
      .state-chat {
        min-height: 28rem;
        border-top: 1px solid #dbe3eb;
        border-left: 0;
      }
    }
    @media (max-width: 44rem) {
      .two-card-grid {
        grid-template-columns: 1fr;
      }
    }
  `,
})
export class StateFeatureComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly copilotKit = inject(CopilotKit);
  protected readonly feature =
    (this.route.snapshot.data["feature"] as string | undefined) ??
    "shared-state-read-write";
  private readonly agentId = agentIdForCurrentIntegration(this.feature);
  private readonly agentStore = injectAgentStore(this.agentId);
  protected readonly isRunning = computed(() => this.agentStore().isRunning());
  protected readonly readWriteState = computed(() =>
    readWriteState(this.agentStore().state()),
  );
  protected readonly recipe = computed(() =>
    readRecipeState(this.agentStore().state()),
  );
  protected readonly document = computed(() =>
    readDocumentState(this.agentStore().state()),
  );
  protected readonly userName = signal("Atai");
  protected readonly timezone = signal("America/Los_Angeles");
  protected readonly recentActivity = signal<string[]>([
    ACTIVITIES[0],
    ACTIVITIES[2],
  ]);
  protected readonly error = signal<string | null>(null);

  protected readonly workspaceLabel = computed(() => {
    switch (this.feature) {
      case "shared-state-read-write":
        return "Bidirectional shared state";
      case "shared-state-read":
        return "Recipe state editor";
      case "shared-state-streaming":
        return "Streaming document state";
      default:
        return "Read-only agent context";
    }
  });

  protected readonly chatPlaceholder = computed(() => {
    switch (this.feature) {
      case "shared-state-streaming":
        return "Ask me to write something...";
      case "readonly-state-agent-context":
        return "Ask about your context...";
      case "shared-state-read-write":
        return "Chat with the agent...";
      default:
        return "Type a message...";
    }
  });

  private readonly nameContext = computed(() => ({
    description: "The user's name.",
    value: this.userName(),
  }));
  private readonly timezoneContext = computed(() => ({
    description: "The user's timezone.",
    value: this.timezone(),
  }));
  private readonly activityContext = computed(() => ({
    description: "The user's recent activity.",
    value: JSON.stringify(this.recentActivity()),
  }));

  constructor() {
    effect(() => {
      const store = this.agentStore();
      const state = store.state();
      if (
        this.feature === "shared-state-read-write" &&
        !hasStateSlot(state, "preferences")
      ) {
        store.agent.setState({ preferences: INITIAL_PREFERENCES, notes: [] });
      }
      if (
        this.feature === "shared-state-read" &&
        !hasStateSlot(state, "recipe")
      ) {
        store.agent.setState({ recipe: INITIAL_RECIPE });
      }
    });

    if (this.feature === "readonly-state-agent-context") {
      connectAgentContext(this.nameContext);
      connectAgentContext(this.timezoneContext);
      connectAgentContext(this.activityContext);
    }
  }

  protected setPreferences(preferences: Preferences): void {
    this.agentStore().agent.setState({
      preferences,
      notes: this.readWriteState().notes,
    });
  }

  protected clearNotes(): void {
    this.agentStore().agent.setState({
      preferences: this.readWriteState().preferences,
      notes: [],
    });
  }

  protected setRecipe(recipe: Recipe): void {
    this.agentStore().agent.setState({ recipe });
  }

  protected async improveRecipe(): Promise<void> {
    if (this.isRunning()) return;
    const agent = this.agentStore().agent;
    agent.addMessage({
      id: createMessageId(),
      role: "user",
      content: "Improve the recipe",
    });
    this.error.set(null);
    try {
      await this.copilotKit.core.runAgent({ agent });
    } catch (error: unknown) {
      this.error.set(
        error instanceof Error ? error.message : "The recipe run failed.",
      );
    }
  }
}

function hasStateSlot(state: unknown, slot: string): boolean {
  return state !== null && typeof state === "object" && slot in state;
}

function createMessageId(): string {
  return (
    globalThis.crypto?.randomUUID?.() ??
    `angular-state-${Date.now()}-${Math.random().toString(16).slice(2)}`
  );
}

