multimodal-message.content:
export function createMultimodalMessage(
  spec: Pick<SampleSpec, "filename" | "mimeType" | "autoPrompt">,
  base64: string,
  size: number,
  id: string,
): MediaAgentMessage {
  return {
    id,
    role: "user",
    content: [
      { type: "text", text: spec.autoPrompt },
      {
        type: spec.mimeType === "application/pdf" ? "document" : "image",
        source: {
          type: "data",
          value: base64,
          mimeType: spec.mimeType,
        },
        metadata: { filename: spec.filename, size },
      },
    ],
  };
}

frontend-tool-registration.content:
/** Create the frontend tool that applies a requested CSS gradient. */
export function createBackgroundTool(
  background: WritableSignal<string>,
): FrontendToolConfig<BackgroundToolArgs> {
  return {
    name: "change_background",
    description: "Change the application background to a CSS gradient.",
    parameters: z.object({
      background: z.string().optional(),
      color: z.string().optional(),
    }),
    handler: async (args) => {
      const next = resolveGradient(args.background ?? args.color);
      background.set(next);
      return { background: next };
    },
  };
}

a2ui-styling.content:
.a2ui-row {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  width: 100%;
}

.a2ui-column {
  display: flex;
  flex-direction: column;
  width: 100%;
}

[data-testid="declarative-card"],
.a2ui-chart-card,
.a2ui-flight-card {
  display: block;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: 0.9rem;
  background: white;
  box-shadow: 0 8px 22px -18px rgb(15 23 42 / 0.4);
}

.a2ui-metric {
  display: grid;
  min-width: 8rem;
  gap: 0.25rem;
}

.a2ui-metric > span,
.a2ui-metric > small {
  color: var(--muted);
  font-size: 0.75rem;
}

.a2ui-metric > strong {
  font-size: 1.4rem;
}

.a2ui-status,
.a2ui-airline {
  display: inline-flex;
  width: fit-content;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  background: #eef2ff;
  font-size: 0.75rem;
  font-weight: 700;
}

.a2ui-status-success {
  background: #dcfce7;
  color: #166534;
}
.a2ui-status-warning {
  background: #fef3c7;
  color: #92400e;
}
.a2ui-status-error {
  background: #fee2e2;
  color: #991b1b;
}
